import{_ as t,o as i,c as o,ag as e}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"게티어 문제","slug":"게티어-문제","link":"#게티어-문제","children":[]},{"level":2,"title":"해결 시도 1 — 인과적 접근","slug":"해결-시도-1-—-인과적-접근","link":"#해결-시도-1-—-인과적-접근","children":[]},{"level":2,"title":"해결 시도 2 — 인식정당성 이론","slug":"해결-시도-2-—-인식정당성-이론","link":"#해결-시도-2-—-인식정당성-이론","children":[]},{"level":2,"title":"토대론","slug":"토대론","link":"#토대론","children":[]},{"level":2,"title":"정합론 (재검토)","slug":"정합론-재검토","link":"#정합론-재검토","children":[]}],"relativePath":"philosophy/Epistemology/08. 게티어 문제.md","filePath":"philosophy/Epistemology/08. 게티어 문제.md"}'),r={name:"philosophy/Epistemology/08. 게티어 문제.md"};function a(n,l,s,u,g,h){return i(),o("div",null,[...l[0]||(l[0]=[e('<h2 id="게티어-문제" tabindex="-1">게티어 문제 <a class="header-anchor" href="#게티어-문제" aria-label="Permalink to &quot;게티어 문제&quot;">​</a></h2><p>믿음·진리·인식정당성 조건(JTB)이 지식의 필요조건이 될 수는 있지만, 충분조건은 될 수 없음을 보여주는 반례들 — 이러한 조건을 수정하여 지식의 정의를 다시 세울 필요가 제기됨.</p><h2 id="해결-시도-1-—-인과적-접근" tabindex="-1">해결 시도 1 — 인과적 접근 <a class="header-anchor" href="#해결-시도-1-—-인과적-접근" aria-label="Permalink to &quot;해결 시도 1 — 인과적 접근&quot;">​</a></h2><p>&quot;소크라테스는 죽는다&quot; → &quot;모든 사람은 죽는다&quot;처럼, 두 개별적 사실이 인과적으로 연결되어 있다는 것이 무슨 의미인지 묻는 접근. 예: &quot;소크라테스는 죽는다&quot;는 사실과 &quot;소크라테스는 독극물을 마셨다&quot;는 사실은 인과적으로 연결되어 있는 것처럼 보임 → 참인 믿음이 그 사실의 원인과 인과적으로 연결되어 있어야 지식이라고 봄.</p><ul><li>인과적 설명이 원리적으로 불가능한 것은 아니지만, 실제로 그 인과 연쇄를 규명하는 것은 까다로움</li><li>반례를 통해 (게티어 문제의 핵심인) <strong>우연적 참</strong>의 문제가 여전히 해결되지 않음을 보일 수 있음</li></ul><h2 id="해결-시도-2-—-인식정당성-이론" tabindex="-1">해결 시도 2 — 인식정당성 이론 <a class="header-anchor" href="#해결-시도-2-—-인식정당성-이론" aria-label="Permalink to &quot;해결 시도 2 — 인식정당성 이론&quot;">​</a></h2><p>게티어 문제 자체에 대한 만족스러운 해결책이 되지는 못하지만, 지식과 인식정당성 사이의 연관성을 다시 짚어보는 접근.</p><p>하나의 믿음은 다른 믿음들에 의해 정당화되고, 그 다른 믿음들 또한 또 다른 믿음들에 의해 정당화됨 — 이 정당화의 사슬을 어떻게 이해할 것인가에 따라 두 입장으로 갈림:</p><ul><li><strong>정합론</strong>: 어떤 믿음은 오직 다른 믿음들과의 정합 관계를 통해서만 정당화됨</li><li><strong>토대론</strong>: 다른 믿음에 의존하지 않고도 스스로 일정 수준의 인식정당성을 갖는 <strong>정당한 기초 믿음</strong>이 존재함 (비추론적 인식정당성) — 예: 단순한 논리적·수학적 진리에 대한 믿음, 자신의 심적 태도·상태에 대한 믿음</li></ul><h2 id="토대론" tabindex="-1">토대론 <a class="header-anchor" href="#토대론" aria-label="Permalink to &quot;토대론&quot;">​</a></h2><p>정당한 기초믿음이 존재하며, 비기초믿음은 (직접적이든 궁극적으로든) 기초믿음에 의존해 정당화됨.</p><p><strong>후퇴논증(regress argument)</strong></p><ol><li>비기초믿음이 존재한다.</li><li>이러한 믿음은 다른 믿음들의 연쇄적 계열 형식으로 정당화된다.</li><li>그 연쇄는 (a) 정당하지 않은 믿음으로 종결되거나, (b) 무한히 계속되거나, (c) 순환적이거나, (d) 기초믿음으로 종결되는 네 가지 경우뿐이다.</li><li>(a)~(c)는 모두 문제가 있으므로 (d)만 남는다.</li></ol><ul><li><strong>(a) 정당하지 않은 믿음으로 종결</strong>: 그 지점부터는 정당화가 끊기므로 애초에 전체 사슬이 정당화되지 못함</li><li><strong>(b) 무한히 계속</strong>: 세 가지 이유로 문제 <ul><li>심리적: 인간은 무한한 것을 실제로 인식할 수 없음</li><li>논리적: 무한히 퇴행한다면 어떤 것이 인식적으로 정당한지 평가할 기준점이 없음</li><li>규범적: 무한히 이어진다면, 믿음에 반례가 주어졌을 때 사슬의 어디부터 수정해야 할지 알 수 없음</li></ul></li><li><strong>(c) 순환적</strong>: 자기 자신에 의해 정당화되는 것처럼 보이는 문제(선결문제 요구의 오류)</li></ul><p><strong>토대론에 대한 비판</strong></p><ul><li>회의주의자: 애초에 인식적으로 정당한 믿음 자체가 없다고 봄 — 이 입장에서는 무한퇴행 문제 자체가 무의미</li><li><strong>고전적 토대론</strong>: 인식적으로 정당한 믿음을 (1) 의심 불가능한 믿음과 (2) 거기서 연역되는 믿음으로 한정. 그러나 지각 믿음이나 기억 믿음은 의심 가능하므로 기초 믿음이 될 수 없고, 내성적 믿음에서 연역될 수도 없음 → <strong>비판: 기준이 너무 엄격함</strong></li><li><strong>온건한 토대론</strong>: 어떤 믿음을 파기하는 증거가 없는 한 기초믿음으로 인정, 연역 외의 방식으로도 정당화가 가능하다고 봄. 정당성의 원천은 다른 믿음이거나, 진리값·정당성을 지니는 <strong>인지적 상태</strong>(비인지적 상태는 정당성을 지니지 않음) <ul><li>비판: 체계적인 여러 믿음들이 정말로 그렇게 산발적인 기초믿음들 위에 놓여 있다고 할 수 있는가?</li></ul></li></ul><h2 id="정합론-재검토" tabindex="-1">정합론 (재검토) <a class="header-anchor" href="#정합론-재검토" aria-label="Permalink to &quot;정합론 (재검토)&quot;">​</a></h2><p>토대론과 달리, 애초에 정당화되지 않고 홀로 서 있는 &#39;기초믿음&#39; 자체를 인정하지 않고, 믿음들 전체의 정합적 그물망을 통해서만 정당성이 성립한다고 보는 입장. (후퇴논증의 (c) 순환 문제를 오히려 정당화의 본래적 구조로 받아들이려는 시도로 이어짐)</p>',18)])])}const c=t(r,[["render",a]]);export{d as __pageData,c as default};
